import{_ as a,o as s,c as i,a2 as r}from"./chunks/framework.CsGzzEsd.js";const p=JSON.parse('{"title":"Plan CFA niveau II","description":"","frontmatter":{"title":"Plan CFA niveau II"},"headers":[],"relativePath":"fr/blogs/CFA/plan.md","filePath":"fr/blogs/CFA/plan.md"}'),t={name:"fr/blogs/CFA/plan.md"};function n(l,e,o,d,u,m){return s(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="plan-d-apprentissage-du-cfa-niveau-ii" tabindex="-1">Plan d’apprentissage du CFA niveau II <a class="header-anchor" href="#plan-d-apprentissage-du-cfa-niveau-ii" aria-label="Permalink to &quot;Plan d’apprentissage du CFA niveau II&quot;">​</a></h1><blockquote><p><strong>Hypothèse de travail :</strong> une préparation de 24 semaines et environ <strong>12 heures par semaine</strong>. Si l’examen est plus proche, gardez l’ordre mais comprimez les deux premières phases ; ne supprimez pas la phase finale de révision et d’examens blancs.</p></blockquote><h2 id="criteres-d-achevement" tabindex="-1">Critères d’achèvement <a class="header-anchor" href="#criteres-d-achevement" aria-label="Permalink to &quot;Critères d’achèvement&quot;">​</a></h2><ul><li>Terminer chaque lecture du programme et ses questions de fin de chapitre.</li><li>Constituer un carnet compact de formules et d’erreurs, pas un deuxième manuel.</li><li>Atteindre <strong>70 % ou plus sur trois examens blancs chronométrés</strong>, sans thème régulièrement sous 60 %.</li><li>Expliquer sans notes chaque grande méthode d’évaluation, ses hypothèses et ses pièges courants.</li></ul><h2 id="rythme-hebdomadaire" tabindex="-1">Rythme hebdomadaire <a class="header-anchor" href="#rythme-hebdomadaire" aria-label="Permalink to &quot;Rythme hebdomadaire&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Séance</th><th style="text-align:right;">Durée</th><th>Travail</th></tr></thead><tbody><tr><td>3 séances en semaine</td><td style="text-align:right;">90 min chacune</td><td>Apprendre un bloc de concepts, puis faire 15 à 25 questions à livre fermé.</td></tr><tr><td>1 courte séance en semaine</td><td style="text-align:right;">45 min</td><td>Rappel des formules et revue du carnet d’erreurs.</td></tr><tr><td>Travail de fond le week-end</td><td style="text-align:right;">5–6 h</td><td>Terminer le thème, exercices mixtes et revue d’un item set.</td></tr></tbody></table><p>Appliquez une <strong>répartition 40/60</strong> : au plus 40 % de lecture ou de vidéo ; au moins 60 % de récupération active, de calculs et d’item sets.</p><h2 id="feuille-de-route-sur-24-semaines" tabindex="-1">Feuille de route sur 24 semaines <a class="header-anchor" href="#feuille-de-route-sur-24-semaines" aria-label="Permalink to &quot;Feuille de route sur 24 semaines&quot;">​</a></h2><h3 id="phase-1-—-cartographier-et-diagnostiquer-semaines-1–2" tabindex="-1">Phase 1 — Cartographier et diagnostiquer (semaines 1–2) <a class="header-anchor" href="#phase-1-—-cartographier-et-diagnostiquer-semaines-1–2" aria-label="Permalink to &quot;Phase 1 — Cartographier et diagnostiquer (semaines 1–2)&quot;">​</a></h3><ul><li>Vérifier la date d’examen et la version actuelle du programme dans les ressources candidats du CFA.</li><li>Passer un diagnostic de 60 à 90 questions sans préparation.</li><li>Étiqueter chaque erreur : <code>knowledge</code> (connaissance), <code>formula</code> (formule), <code>interpretation</code> (interprétation), <code>calculator</code> (calculatrice) ou <code>time</code> (temps).</li><li>Créer un carnet d’erreurs : source de la question, pourquoi la mauvaise réponse semblait juste, règle correcte, date de révision.</li></ul><h3 id="phase-2-—-premier-passage-semaines-3–14" tabindex="-1">Phase 2 — Premier passage (semaines 3–14) <a class="header-anchor" href="#phase-2-—-premier-passage-semaines-3–14" aria-label="Permalink to &quot;Phase 2 — Premier passage (semaines 3–14)&quot;">​</a></h3><p>Étudier dans un ordre où la compréhension se cumule :</p><ol><li>Méthodes quantitatives et économie</li><li>Analyse des états financiers</li><li>Émetteurs</li><li>Évaluation des actions</li><li>Titres à revenu fixe</li><li>Produits dérivés</li><li>Investissements alternatifs</li><li>Gestion de portefeuille</li></ol><p>Gardez l’éthique active avec une courte série chaque semaine. À la fin de chaque thème, faites une série mixte chronométrée et rédigez une synthèse d’une page : décisions clés, formules et modes d’échec.</p><h3 id="phase-3-—-integration-semaines-15–19" tabindex="-1">Phase 3 — Intégration (semaines 15–19) <a class="header-anchor" href="#phase-3-—-integration-semaines-15–19" aria-label="Permalink to &quot;Phase 3 — Intégration (semaines 15–19)&quot;">​</a></h3><ul><li>Remplacer le travail chapitre par chapitre par des item sets mixtes.</li><li>Faire deux blocs chronométrés de 45 à 60 minutes chaque semaine.</li><li>Refaire chaque erreur consignée après 2 jours, 1 semaine et 3 semaines.</li><li>Associer les domaines liés : analyse financière ↔ actions, économie ↔ gestion de portefeuille, revenu fixe ↔ dérivés.</li><li>Terminer chaque semaine par un tableau de scores par thème et par type d’erreur.</li></ul><h3 id="phase-4-—-mode-examen-semaines-20–23" tabindex="-1">Phase 4 — Mode examen (semaines 20–23) <a class="header-anchor" href="#phase-4-—-mode-examen-semaines-20–23" aria-label="Permalink to &quot;Phase 4 — Mode examen (semaines 20–23)&quot;">​</a></h3><ul><li>Faire un examen blanc complet et chronométré chaque week-end, dans les conditions réelles.</li><li>Passer au moins autant de temps à corriger un examen blanc qu’à le faire.</li><li>En semaine, ne travailler que les deux thèmes les plus faibles ; éviter les relectures au hasard.</li><li>Réécrire de mémoire la fiche de formules essentielles une fois par semaine.</li></ul><h3 id="phase-5-—-affutage-semaine-24" tabindex="-1">Phase 5 — Affûtage (semaine 24) <a class="header-anchor" href="#phase-5-—-affutage-semaine-24" aria-label="Permalink to &quot;Phase 5 — Affûtage (semaine 24)&quot;">​</a></h3><ul><li>Faire des séries mixtes courtes et de qualité ; arrêter les examens blancs complets quelques jours avant l’épreuve.</li><li>Revoir l’éthique, les formules, les erreurs récurrentes, les manipulations de calculatrice et la logistique de l’examen.</li><li>Protéger son sommeil et sa confiance ; n’ajouter aucune nouvelle ressource.</li></ul><h2 id="modele-de-bilan-hebdomadaire" tabindex="-1">Modèle de bilan hebdomadaire <a class="header-anchor" href="#modele-de-bilan-hebdomadaire" aria-label="Permalink to &quot;Modèle de bilan hebdomadaire&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes min-light min-dark vp-code" tabindex="0"><code><span class="line"><span>Heures prévues / réalisées :</span></span>
<span class="line"><span>Questions tentées / taux de réussite :</span></span>
<span class="line"><span>Thème le plus faible et type d’erreur :</span></span>
<span class="line"><span>Un concept que je peux maintenant enseigner :</span></span>
<span class="line"><span>Un changement pour la semaine prochaine :</span></span></code></pre></div><h2 id="les-sept-premiers-jours" tabindex="-1">Les sept premiers jours <a class="header-anchor" href="#les-sept-premiers-jours" aria-label="Permalink to &quot;Les sept premiers jours&quot;">​</a></h2><ul><li>[ ] Noter la date d’examen, les semaines restantes et le budget horaire hebdomadaire.</li><li>[ ] Passer et corriger le diagnostic.</li><li>[ ] Créer le carnet d’erreurs et les fiches de formules.</li><li>[ ] Choisir les deux premiers blocs thématiques.</li><li>[ ] Inscrire toutes les séances dans l’agenda avant le début de la semaine.</li></ul><h2 id="notes-de-modules" tabindex="-1">Notes de modules <a class="header-anchor" href="#notes-de-modules" aria-label="Permalink to &quot;Notes de modules&quot;">​</a></h2><p>Après ce plan, suivez « Page suivante » en bas de page pour ouvrir la première note de module ; toutes les notes sont rangées dans l’ordre du programme dans le <a href="/fr/blogs/0-start.html#cfa-level-ii-directory">sommaire de la base d’apprentissage</a>.</p>`,26)])])}const h=a(t,[["render",n]]);export{p as __pageData,h as default};
